function impliedOdds(ra, rb) {
  const total = (ra || 50) + (rb || 50);
  const pA = (ra || 50) / total, pB = (rb || 50) / total, draw = 0.24;
  return { A: parseFloat((1 / (pA * (1 - draw))).toFixed(2)), D: parseFloat((1 / draw).toFixed(2)), B: parseFloat((1 / (pB * (1 - draw))).toFixed(2)) };
}
function genVoucher() { return Math.random().toString(36).slice(2, 8).toUpperCase(); }
function genBetId() { return "BET-" + Math.floor(1000 + Math.random() * 9000); }
function genFixtureId(n) { return "FIX-" + String(n).padStart(3, "0"); }
function nowStr() { return new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); }
const HIDDEN_FILE_INPUT = { position: "absolute", width: 1, height: 1, padding: 0, margin: -1, overflow: "hidden", clip: "rect(0,0,0,0)", whiteSpace: "nowrap", border: 0 };
function ns(v) { return v ? v : "Not set"; }
function safeFormationKey(key) { return FORMATIONS[key] ? key : "4-3-3"; }
function riskLevel(pct) {
  if (pct >= 90) return "CRITICAL";
  if (pct >= 75) return "HIGH";
  if (pct >= 50) return "MEDIUM";
  return "LOW";
}
function riskColor(level) {
  return { LOW: C.pitch, MEDIUM: C.gold, HIGH: "#FF8C42", CRITICAL: C.danger }[level] || C.muted;
}
function getPlayer(players, id) { return players.find((p) => p.id === id) || null; }
function starsFromStrength(s) {
  if (s === null || s === undefined || s === "") return 0;
  const n = Number(s);
  if (isNaN(n) || n <= 0) return 0;
  if (n >= 3500) return 5;
  if (n >= 3200) return 4;
  if (n >= 2900) return 3;
  if (n >= 2600) return 2;
  return 1;
}
function StarRating({ stars, size = 14 }) {
  if (!stars) return <span style={{ fontSize: 11, color: C.muted }}>Unrated</span>;
  return (<span style={{ letterSpacing: 1 }}>{[1, 2, 3, 4, 5].map((i) => (<span key={i} style={{ color: i <= stars ? C.gold : C.line, fontSize: size }}>★</span>))}</span>);
}
async function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result.split(",")[1]);
    r.onerror = () => reject(new Error("Read failed"));
    r.readAsDataURL(file);
  });
}
async function analyzeSquadScreenshot(file) {
  const base64Data = await fileToBase64(file);
  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 500,
      messages: [{
        role: "user",
        content: [
          { type: "image", source: { type: "base64", media_type: file.type || "image/jpeg", data: base64Data } },
          { type: "text", text: 'This is a screenshot from the eFootball game showing a squad/team info screen. Extract these fields and respond with ONLY strict JSON, no markdown fences, no extra commentary: {"playerName": string or null, "teamName": string or null, "managerName": string or null, "formation": string or null, "strength": number or null}. "strength" is the numeric Team Strength value (e.g. 3245). If a field is not visible or you are not confident, use null for it. Do not guess.' },
        ],
      }],
    }),
  });
  const data = await response.json();
  const textBlock = (data.content || []).find((b) => b.type === "text");
  if (!textBlock) throw new Error("No response");
  const cleaned = textBlock.text.replace(/```json|```/g, "").trim();
  return JSON.parse(cleaned);
}

