function PAvatar({ p, size = 88 }) {
  const initials = p ? p.name.slice(0, 2).toUpperCase() : "?";
  const photo = p && p.avatarUrl;
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", flexShrink: 0, background: `radial-gradient(circle at 35% 30%, ${C.electric}55, #0A0E14 75%)`, border: `2px solid ${C.electric}`, boxShadow: `0 0 ${size * 0.35}px ${C.electric}66`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FD, fontWeight: 700, fontSize: size * 0.32, color: C.text, overflow: "hidden" }}>
      {photo ? <img src={photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : initials}
    </div>
  );
}
function Pill({ children, color = C.muted }) { return <span style={{ fontSize: 11, fontFamily: FD, letterSpacing: 0.3, color, border: `1px solid ${color}55`, borderRadius: 999, padding: "3px 9px" }}>{children}</span>; }
function Card({ children, style }) { return <div style={{ background: "rgba(18,25,36,0.82)", backdropFilter: "blur(6px)", border: `1px solid ${C.line}`, borderRadius: 12, padding: 14, ...style }}>{children}</div>; }
