// ---------- Cinematic Background Cycler ----------
// Replaces the old abstract glow background with a slow, dramatic cycle through the uploaded
// images. Only transform/opacity/filter/clip-path are animated (GPU-friendly, no layout thrash),
// the tab pauses the cycle when hidden, and prefers-reduced-motion swaps to a plain crossfade.
const BG_MESSAGES = ["YOU COWARD.", "TAKE THE RISK.", "LET'S PLAY.", "NO GUTS. NO GLORY.", "STEP INTO THE ARENA.", "PROVE IT."];
const BG_EFFECT_ANIM = { zoomBreak: "bgZoomBreak", push3d: "bgPush3D", rotateShatter: "bgRotateShatter", warpGlitch: "bgWarpGlitch" };

function buildBgSequence() {
  const seq = [];
  BG_IMAGES.forEach((img, i) => {
    seq.push({ type: "image", img });
    if (i % 2 === 1) seq.push({ type: "message", text: BG_MESSAGES[Math.floor(i / 2) % BG_MESSAGES.length] });
  });
  return seq;
}

function BackgroundCycler() {
  const sequenceRef = useRef(null);
  if (!sequenceRef.current) sequenceRef.current = buildBgSequence();
  const sequence = sequenceRef.current;
  const [pos, setPos] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(false);
  const timerRef = useRef(null);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const handler = (e) => setReducedMotion(e.matches);
    if (mq.addEventListener) mq.addEventListener("change", handler); else mq.addListener(handler);
    return () => { if (mq.removeEventListener) mq.removeEventListener("change", handler); else mq.removeListener(handler); };
  }, []);

  useEffect(() => {
    const slide = sequence[pos % sequence.length];
    const duration = slide.type === "message" ? 3200 : (reducedMotion ? 9000 : 60000);
    function tick() { setPos((p) => p + 1); }
    function onVis() {
      if (document.hidden) { clearTimeout(timerRef.current); } else { clearTimeout(timerRef.current); timerRef.current = setTimeout(tick, duration); }
    }
    timerRef.current = setTimeout(tick, duration);
    document.addEventListener("visibilitychange", onVis);
    return () => { clearTimeout(timerRef.current); document.removeEventListener("visibilitychange", onVis); };
    // eslint-disable-next-line
  }, [pos, reducedMotion]);

  const slide = sequence[pos % sequence.length];

  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", zIndex: 0, background: "#0A0E14" }}>
      {slide.type === "image" ? (
        <div
          key={pos}
          style={{
            position: "absolute", inset: 0,
            backgroundImage: `url(${slide.img.url})`,
            backgroundSize: "cover", backgroundPosition: "center",
            animation: reducedMotion ? "bgFadeSimple 9s ease-in-out forwards" : `${BG_EFFECT_ANIM[slide.img.effect] || "bgZoomBreak"} 60s ease-in-out forwards`,
            willChange: "transform, opacity, filter",
          }}
        />
      ) : (
        <div key={pos} style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", padding: 30, background: "#0A0E14" }}>
          <div style={{ fontFamily: FD, fontWeight: 700, fontSize: 30, letterSpacing: 1, textAlign: "center", color: "#fff", textShadow: `0 0 20px ${C.danger}, 0 0 50px ${C.danger}99`, animation: reducedMotion ? "none" : "popIn 0.4s ease both" }}>{slide.text}</div>
        </div>
      )}
      <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(10,14,20,0.74) 0%, rgba(10,14,20,0.6) 45%, rgba(10,14,20,0.84) 100%)" }} />
    </div>
  );
}


